arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H "Content-Type: application/json" -d '{"token":"***","types":"public_channel"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR', d.get('error'), d.get('error_code')); sys.exit()
for c in d['channels']:
    if 'product' in c['name'].lower() or 'launch' in c['name'].lower():
        print(c['id'], c['name'])
"

